+			errs:    map[string]error{v4: fmt.Errorf("%w: %w", nettrace.ErrNoRoute, frErr)},
+			verdict: Fail, denySummary: []string{"Réseau", "inaccessible"},
+			wantNoRoute: 1, noRouteFactIn: "Réseau inaccessible",
+		},
+		{
