+// machine's language, lives only in fact values, never in the Summary (Rule 129).
+func TestRouteErrorsAreClassifiedProvenVersusUndetermined(t *testing.T) {
+	const (
+		v4  = "93.184.216.34"
+		v6  = "2606:2800:220:1::1"
+		v4b = "93.184.216.35"
